
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_pc07_opt_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_pc07_opt", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.439417119089030e+01, 2.434649686400661e+01, 2.427631606941563e+01, 2.417289541882846e+01, 2.402101583916856e+01, 2.380004617695145e+01, 2.353530952033114e+01, 2.416834714319353e+01, 2.388413133277875e+01, 2.269503709459348e+01, 1.886851197812494e+01, 5.961945728909992e+00, 9.926098713536834e-01, 1.045191494736180e+00, 1.011262132831599e+00, 9.150530484143576e-01, 8.723199933350824e-01, 9.648831915405587e-01, 6.623855573223886e-01, 5.750019933740846e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


